        setattr(ssl.SSLSocket, method, _make_wrapper(original, _socket_allowed))", "originalFile": """"Blocking-I/O detection for async test contexts.

This module monkey-patches a curated set of blocking I/O primitives so that,
when they are invoked while an asyncio event loop is running in the current
thread, a :class:`BlockingError` is raised instead of silently blocking the
event loop.

Operations invoked outside of a running event loop (for example, from a worker
thread spawned via ``asyncio.to_thread``) are left untouched and behave exactly
as they normally would.

A few well-known, unavoidable blocking call sites are allow-listed so that the
test infrastructure itself keeps working:

* ``time.sleep`` is permitted when a PyDev debugger wait-suspend frame is on the
  call stack (so debugging paused coroutines still works).
* File reads are permitted from the pytest assertion-rewrite machinery and from
  an ``importlib`` ``FileLoader`` (module import).
* File writes are permitted to ``sys.stdout``/``sys.stderr`` and from the pytest
  assertion-rewrite machinery.
"""

from __future__ import annotations

import asyncio
import functools
import importlib.abc
import io
import os
import socket
import ssl
import sys
from types import FrameType

