__all__ = ["BlockingError", "init"]


class BlockingError(Exception):
    """Raised when a blocking I/O operation is detected inside an async context."""


def _in_async_context() -> bool:
    """Return ``True`` when an asyncio event loop is running in this thread."""
    try:
        asyncio.get_running_loop()
    except RuntimeError:
        return False
    return True


def _iter_frames() -> "list[FrameType]":
    """Yield the frames of the current call stack, innermost first."""
    frames = []
    frame: FrameType | None = sys._getframe(1)  # noqa: SLF001
    while frame is not None:
        frames.append(frame)
        frame = frame.f_back
    return frames


def _in_debugger_wait_suspend() -> bool:
    """Return ``True`` if a PyDev debugger wait-suspend frame is on the stack."""
    for frame in _iter_frames():
        code = frame.f_code
        if "wait_suspend" in code.co_name and "pydevd" in code.co_filename:
            return True
        # Some pydevd versions expose the frame purely by name.
        if code.co_name in {"_do_wait_suspend", "do_wait_suspend"}:
            return True
    return False


def _in_pytest_assertion_rewrite() -> bool:
    """Return ``True`` if the pytest assertion-rewrite machinery is on the stack."""
    for frame in _iter_frames():
        filename = frame.f_code.co_filename.replace(os.sep, "/")
        if filename.endswith("_pytest/assertion/rewrite.py"):
            return True
    return False


def _in_file_loader() -> bool:
    """Return ``True`` if an importlib ``FileLoader`` read is on the stack."""
    for frame in _iter_frames():
        if frame.f_code.co_name != "get_data":
            continue
        loader = frame.f_locals.get("self")
        if isinstance(loader, importlib.abc.FileLoader):
            return True
        # ``get_data`` for the frozen bootstrap loader lives in this module.
        if "importlib._bootstrap_external" in frame.f_code.co_filename:
            return True
    return False


