    """Return the stdout/stderr stream objects and their underlying buffers."""
    objects: list[object] = []
    for stream in (sys.stdout, sys.stderr):
        if stream is None:
            continue
        objects.append(stream)
        buffer = getattr(stream, "buffer", None)
        if buffer is not None:
            objects.append(buffer)
            raw = getattr(buffer, "raw", None)
            if raw is not None:
                objects.append(raw)
    return tuple(objects)


def _std_filenos() -> "set[int]":
    """Return the file descriptors backing stdout/stderr (typically ``{1, 2}``)."""
    filenos: set[int] = set()
    for stream in (sys.stdout, sys.stderr):
        try:
            filenos.add(stream.fileno())
        except (OSError, ValueError, AttributeError):
            continue
    return filenos


