    """Reads are allowed from pytest assertion rewriting or a ``FileLoader``."""
    return _in_pytest_assertion_rewrite() or _in_file_loader()


def _write_allowed(*args, **_kwargs) -> bool:
    """Writes to stdout/stderr or from pytest assertion rewriting are allowed."""
    if _in_pytest_assertion_rewrite():
