def _sleep_allowed(*_args, **_kwargs) -> bool:
    """``time.sleep`` is allowed while paused in the PyDev debugger."""
    return _in_debugger_wait_suspend()


def _socket_allowed(*args, **_kwargs) -> bool:
    """Socket ops on a non-blocking socket never block, so they are allowed.

    The asyncio event loop drives all of its own sockets (including its internal
    self-pipe) in non-blocking mode, so this keeps the loop machinery working
    while still catching genuinely blocking socket calls.
    """
    if not args:
        return False
    sock = args[0]
    getblocking = getattr(sock, "getblocking", None)
    if getblocking is None:
        return False
    try:
        return not getblocking()
    except OSError:
        return False


